/**
 * Horizontal auto-scrolling showcase of rounded 9:16 format cards. Each card shows a
 * real frame generated by CloutHook's own image pipeline (FLUX on cadence-gen) —
 * the product demoing itself. Pure CSS marquee (`.animate-marquee` from globals.css,
 * gated by prefers-reduced-motion); pauses on hover.
 *
 * Presentational only — safe on the server.
 */

const FORMATS_BASE = `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/assets/landing`;

type Sample = {
  label: string;
  tag: string;
  slug: string;
  grad: string; // paints behind the image while it loads
};

const SAMPLES: Sample[] = [
  { label: "Founder hot take", tag: "Talking head", slug: "founder-hot-take", grad: "linear-gradient(160deg,#5c8cff,#7a6cff 55%,#a06bff)" },
  { label: "Product teardown", tag: "AI b-roll", slug: "product-teardown", grad: "linear-gradient(160deg,#7a6cff,#a06bff 60%,#5c8cff)" },
  { label: "Day-in-the-life", tag: "Replace BG", slug: "day-in-the-life", grad: "linear-gradient(160deg,#3f6dff,#7a6cff 50%,#b07bff)" },
  { label: "Hook + payoff", tag: "Auto-captioned", slug: "hook-payoff", grad: "linear-gradient(160deg,#6e7bff,#a06bff)" },
  { label: "Listicle / tips", tag: "Cut to beat", slug: "listicle-tips", grad: "linear-gradient(160deg,#8a6cff,#5c8cff 60%,#a06bff)" },
  { label: "Case study", tag: "Brand kit", slug: "case-study", grad: "linear-gradient(160deg,#5c8cff,#a06bff 70%,#7a6cff)" },
];

function ShowcaseCard({ s }: { s: Sample }) {
  return (
    <div className="group relative aspect-[9/16] w-[180px] shrink-0 overflow-hidden rounded-2xl border border-white/12 shadow-[0_18px_50px_-22px_rgba(0,0,0,0.9)] transition-transform duration-300 hover:-translate-y-1.5 sm:w-[210px]">
      {/* gradient paints first; the real frame loads over it */}
      <div className="absolute inset-0" style={{ background: s.grad }} />
      {/* eslint-disable-next-line @next/next/no-img-element -- marquee duplicates make next/image overhead pointless */}
      <img
        src={`${FORMATS_BASE}/${s.slug}.jpg`}
        alt={`${s.label} — ${s.tag} format made with CloutHook`}
        loading="lazy"
        decoding="async"
        className="absolute inset-0 h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.04]"
      />
      {/* darkening for label legibility */}
      <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-black/10" />
      {/* sheen sweep on hover */}
      <div className="absolute inset-0 opacity-0 transition-opacity duration-300 group-hover:opacity-100">
        <div className="sheen absolute inset-0" />
      </div>

      <div className="absolute inset-x-0 bottom-0 p-3.5">
        <span className="inline-flex rounded-full bg-white/15 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-white/90 backdrop-blur-sm">
          {s.tag}
        </span>
        <p className="mt-2 text-sm font-semibold text-white drop-shadow">{s.label}</p>
      </div>
    </div>
  );
}

export function ShowcaseGallery() {
  // Render the set twice so the -50% marquee translate loops seamlessly.
  const loop = [...SAMPLES, ...SAMPLES];
  return (
    <div className="group/marquee relative w-full overflow-hidden">
      {/* edge fades so cards dissolve instead of hard-cutting at the viewport */}
      <div className="pointer-events-none absolute inset-y-0 left-0 z-10 w-16 bg-gradient-to-r from-[var(--background)] to-transparent sm:w-28" />
      <div className="pointer-events-none absolute inset-y-0 right-0 z-10 w-16 bg-gradient-to-l from-[var(--background)] to-transparent sm:w-28" />

      <div className="animate-marquee flex w-max gap-4 [animation-duration:46s] group-hover/marquee:[animation-play-state:paused] sm:gap-5">
        {loop.map((s, i) => (
          <ShowcaseCard key={`${s.label}-${i}`} s={s} />
        ))}
      </div>
    </div>
  );
}
